from __future__ import annotations


TEMPLATE_PATH = 'frontend/app/customers/page.tsx'
TEMPLATE_CONTENT = '"use client";\n\nimport { FormEvent, useEffect, useState } from "react";\nimport { createCustomer, getCustomers } from "../../lib/api";\nimport { SAFE_ERROR_MESSAGES } from "../../lib/errors";\n\ntype Customer = {\n  id: number;\n  name: string;\n  email?: string | null;\n  phone?: string | null;\n  company?: string | null;\n};\n\nexport default function CustomersPage() {\n  const [customers, setCustomers] = useState<Customer[]>([]);\n  const [name, setName] = useState("");\n  const [email, setEmail] = useState("");\n  const [company, setCompany] = useState("");\n  const [errorMessage, setErrorMessage] = useState("");\n\n  async function loadCustomers() {\n    setErrorMessage("");\n\n    try {\n      const data = await getCustomers();\n      setCustomers(data as Customer[]);\n    } catch {\n      setErrorMessage(SAFE_ERROR_MESSAGES.customersLoadFailed);\n    }\n  }\n\n  useEffect(() => {\n    loadCustomers();\n  }, []);\n\n  async function handleCreateCustomer(event: FormEvent<HTMLFormElement>) {\n    event.preventDefault();\n    setErrorMessage("");\n\n    try {\n      await createCustomer({\n        name,\n        email: email || undefined,\n        company: company || undefined,\n      });\n\n      setName("");\n      setEmail("");\n      setCompany("");\n      await loadCustomers();\n    } catch {\n      setErrorMessage(SAFE_ERROR_MESSAGES.customerCreateFailed);\n    }\n  }\n\n  return (\n    <main className="px-6 py-8">\n      <h1 className="mb-6 text-2xl font-semibold">Customers</h1>\n\n      <form onSubmit={handleCreateCustomer} className="mb-8 grid gap-3 md:grid-cols-4">\n        <input\n          className="rounded border px-3 py-2"\n          placeholder="Name"\n          value={name}\n          onChange={(event) => setName(event.target.value)}\n        />\n\n        <input\n          className="rounded border px-3 py-2"\n          placeholder="Email"\n          type="email"\n          value={email}\n          onChange={(event) => setEmail(event.target.value)}\n        />\n\n        <input\n          className="rounded border px-3 py-2"\n          placeholder="Company"\n          value={company}\n          onChange={(event) => setCompany(event.target.value)}\n        />\n\n        <button className="rounded bg-black px-4 py-2 text-white" type="submit">\n          Add Customer\n        </button>\n      </form>\n\n      {errorMessage ? (\n        <p className="mb-4 text-sm text-red-600">{errorMessage}</p>\n      ) : null}\n\n      <div className="overflow-x-auto rounded border">\n        <table className="w-full text-left text-sm">\n          <thead>\n            <tr className="border-b">\n              <th className="px-3 py-2">Name</th>\n              <th className="px-3 py-2">Email</th>\n              <th className="px-3 py-2">Company</th>\n            </tr>\n          </thead>\n          <tbody>\n            {customers.map((customer) => (\n              <tr className="border-b" key={customer.id}>\n                <td className="px-3 py-2">{customer.name}</td>\n                <td className="px-3 py-2">{customer.email || "-"}</td>\n                <td className="px-3 py-2">{customer.company || "-"}</td>\n              </tr>\n            ))}\n          </tbody>\n        </table>\n      </div>\n    </main>\n  );\n}\n'
